Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -22,4 +22,37 @@
 <div class="bottom-area"><div class="help-pill"><span>Movete con</span><b class="kbd">W</b><b class="kbd">A</b><b class="kbd">S</b><b class="kbd">D</b><span>o el mando</span></div><div class="controls"><div class="stick-shell" id="stickShell" aria-label="Control de movimiento"><div class="stick" id="stick">✦</div></div><div class="actions"><button class="action primary" id="gatherBtn"><span class="action-icon">🌱</span><span>RECOLECTAR</span></button><button class="action" id="nestBtn"><span class="action-icon">⌂</span><span>IR AL NIDO</span></button></div></div></div>
 <div class="shade" id="pauseShade"><div class="pause-card"><div class="big">🍃</div><h2>Un respiro en el bosque</h2><p>Tu exploradora espera tranquila. Cuando quieras, seguimos buscando provisiones.</p><button class="resume" id="resumeBtn">Volver al claro</button></div></div>
 </div>
 <script>
+(()=>{'use strict';
+const canvas=document.getElementById('world'),ctx=canvas.getContext('2d',{alpha:false}),miniAnt=document.getElementById('miniAnt');
+const W=2480,H=1740,rand=(seed)=>()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
+const rng=rand(417),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+const world=document.createElement('canvas');world.width=W;world.height=H;const g=world.getContext('2d');
+const ant={x:W*.49,y:H*.51,angle:-.35,speed:178,carry:0};let food=0,mode='idle',target=null,paused=false,muted=true,toastTimer=0,clock=0,harvestTimer=0;
+const nest={x:W*.49,y:H*.51};
+const obstacles=[],trees=[],rocks=[],plants=[],resources=[];
+function rounded(x,y,w,h,r){g.beginPath();g.roundRect(x,y,w,h,r);}
+function path(points,width,color){g.beginPath();g.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)g.lineTo(points[i][0],points[i][1]);g.lineWidth=width;g.lineCap='round';g.lineJoin='round';g.strokeStyle=color;g.stroke()}
+function drawGround(){
+ let bg=g.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#82925b');bg.addColorStop(.47,'#71864f');bg.addColorStop(1,'#586f45');g.fillStyle=bg;g.fillRect(0,0,W,H);
+ // Mossy clearings and sunlit patches
+ for(let i=0;i<75;i++){let x=rng()*W,y=rng()*H,r=50+rng()*190;g.beginPath();g.ellipse(x,y,r,r*(.42+rng()*.46),rng()*Math.PI,0,Math.PI*2);g.fillStyle=i%3===0?'#99a26818':i%3===1?'#344e3510':'#c0aa6510';g.fill()}
+ // Shallow pond, tucked into the southeast corner
+ g.save();g.translate(W*.76,H*.69);g.rotate(-.27);g.beginPath();g.ellipse(0,0,275,156,0,0,Math.PI*2);g.fillStyle='#496d6750';g.fill();g.beginPath();g.ellipse(0,-5,250,137,0,0,Math.PI*2);let water=g.createLinearGradient(-100,-120,100,130);water.addColorStop(0,'#81a998');water.addColorStop(1,'#5e8e83');g.fillStyle=water;g.fill();g.lineWidth=5;g.strokeStyle='#bdd0a466';g.stroke();
+ for(let i=0;i<24;i++){let x=(rng()-.5)*380,y=(rng()-.5)*210;g.beginPath();g.ellipse(x,y,8+rng()*26,2+rng()*5,-.3,0,Math.PI*2);g.fillStyle='#d5dfbc38';g.fill()}
+ g.restore();
+ // Winding, well-trodden trails connect the nest to the clearings
+ path([[W*.49,H*.51],[W*.42,H*.47],[W*.36,H*.43],[W*.31,H*.35],[W*.25,H*.32],[W*.18,H*.28]],74,'#b49a6651');path([[W*.49,H*.51],[W*.56,H*.47],[W*.61,H*.42],[W*.69,H*.43],[W*.76,H*.48]],62,'#b49a6645');path([[W*.49,H*.51],[W*.53,H*.58],[W*.49,H*.65],[W*.43,H*.71],[W*.34,H*.76]],55,'#b49a6642');path([[W*.49,H*.51],[W*.45,H*.56],[W*.37,H*.57],[W*.29,H*.61]],39,'#c7ab7040');
+ // Dense little blades of grass and leaf litter
+ for(let i=0;i<4400;i++){let x=rng()*W,y=rng()*H;if(Math.abs(x-W*.76)<280&&Math.abs(y-H*.69)<165)continue;let l=2+rng()*8;g.beginPath();g.moveTo(x,y);g.quadraticCurveTo(x+(rng()-.5)*5,y-l*.6,x+(rng()-.5)*8,y-l);g.strokeStyle=['#354f35a8','#d0b66b72','#b9c28275','#435d3ca8','#d6cc9a5c'][Math.floor(rng()*5)];g.lineWidth=.8+rng()*1.3;g.stroke()}
+ for(let i=0;i<520;i++){let x=rng()*W,y=rng()*H,r=1+rng()*2.2;g.fillStyle=rng()>.5?'#4c54365c':'#d6c49270';g.beginPath();g.ellipse(x,y,r,r*.65,rng()*3,0,Math.PI*2);g.fill()}
+ // Border foliage softens the playable clearing
+ let edge=g.createRadialGradient(W*.5,H*.48,Math.min(W,H)*.34,W*.5,H*.48,Math.max(W,H)*.72);edge.addColorStop(0,'#00000000');edge.addColorStop(1,'#172a245c');g.fillStyle=edge;g.fillRect(0,0,W,H);
+}
+function addTree(x,y,s=1){trees.push({x,y,r:24*s});obstacles.push({x,y,r:22*s});}
+function drawTree(x,y,s){g.save();g.translate(x,y);g.scale(s,s);g.fillStyle='#273a2b55';g.beginPath();g.ellipse(9,17,40,22,0,0,Math.PI*2);g.fill();g.fillStyle='#594d36';g.beginPath();g.ellipse(0,9,10,19,0,0,Math.PI*2);g.fill();
+ let layers=[[-14,-8,38,'#496642'],[8,-20,42,'#587849'],[-13,-30,29,'#668550'],[15,-39,26,'#78935a']];for(let [x0,y0,r,c] of layers){g.beginPath();g.arc(x0,y0,r,0,Math.PI*2);g.fillStyle=c;g.fill();g.beginPath();g.arc(x0-8,y0-9,r*.54,3.2,5.4);g.fillStyle='#bdc27a26';g.fill()}
+ for(let i=0;i<5;i++){g.beginPath();g.ellipse((rng()-.5)*43,-24+rng()*34,4,2,rng(),0,Math.PI*2);g.fillStyle='#d0d68a74';g.fill()}g.restore()}
+function addRock(x,y,s=1){rocks.push({x,y,r:15*s});obstacles.push({x,y,r:13*s});}
+function drawRock(x,y,s){g.save();g.translate(x,y);g.scale(s,s);g.fillStyle='#1f302c47';g.beginPath();g.ellipse(5,9,26,13,0,0,Math.PI*2);g.fill();g.beginPath();g.moveTo(-22,5);g.lineTo(-16,-11);g.lineTo(-2,-20);g.lineTo(13,-15);g.lineTo(24,-1);g.lineTo(19,12);g.lineTo(-13,15);g.closePath();let rg=g.createLinearGradient(-15,-18,14,13);rg.addColorStop(0,'#a4a99b');rg.addColorStop(.4,'#737d70');rg.addColorStop(1,'#4e5e55');g.fillStyle=rg;g.fill();g.strokeStyle='#d4d5ba68';g.lineWidth=2;g.beginPath();g.moveTo(-15,-8);g.lineTo(-2,-16);g.lineTo(7,-14);g.stroke();g.restore()}
+function drawPlant(x,y,type,s=1){g.save();g.translate(x,y);g.scale(s,s);g.strokeStyle='#405a36';g.lineWidth=2;g.beginPath();g.moveTo(0,10);g.quadraticCurveTo(-3,-8,0,-18);g.stroke();g.beginPath();g.moveTo(-1,-4);g.quadraticCurveTo(-13,-15,-15,-6);g.quadraticCurveTo(-8,1,-1,-1);g.moveTo(0,-9);g.quadraticCurveTo(10,-20,14,-11);g.quadraticCurveTo(10,-3,1,-6);g.stroke();if(type==='berry'){for(let i=0;i<3;i++){g.beginPath();g.arc(-5+i*6,-20+(i%2)*3,4,0,Math.PI*2);g.fillStyle=['#d97571','#cf656a','#e58b77'][i];g.fill();g.fillStyle='#f9c0a266';g.beginPath();g.arc(-6+i*6,-21+(i%2)*3,1.2,0,Math.PI*2);g.fill()}}else{g.beginPath();g.ellipse(1,-21,4,7,-.5,0,Math.PI*2);g.fillStyle='#d3b86e';g.fill();g.beginPath();g.ellipse(0,-21,1,4,0,0,Math.PI*2);g.strokeStyle='#eee0a1';g.lineWidth=1;g.stroke()}g.restore()}

input.newString:
g.restore()}
function drawNest(){g.save();g.translate(nest.x,nest.y);g.fillStyle='#283923';g.beginPath();g.ellipse(0,8,50,37,-.3,0,Math.PI*2);g.fill();g.fillStyle='#aa9362';g.beginPath();g.ellipse(0,3,44,31,-.3,0,Math.PI*2);g.fill();g.fillStyle='#362e22';g.beginPath();g.ellipse(1,1,29,21,-.3,0,Math.PI*2);g.fill();g.fillStyle='#181e17';g.beginPath();g.ellipse(3,3,20,14,-.3,0,Math.PI*2);g.fill();g.strokeStyle='#d3bb7d';g.lineWidth=3;for(let i=0;i<11;i++){let a=i/11*Math.PI*2;g.beginPath();g.ellipse(Math.cos(a)*39,Math.sin(a)*26,5,3,a,0,Math.PI*2);g.fillStyle=i%2?'#8a7149':'#c8af70';g.fill()}g.fillStyle='#e7d8a2';g.font='600 13px system-ui';g.textAlign='center';g.fillText('NIDO',0,54);g.restore()}
function makeMap(){drawGround();let candidates=[];for(let i=0;i<54;i++){let x=55+rng()*(W-110),y=55+rng()*(H-110);if(dist({x,y},nest)<155)continue;if(Math.abs(x-W*.76)<330&&Math.abs(y-H*.69)<210)continue;candidates.push({x,y,s:.65+rng()*.82})}candidates.sort((a,b)=>a.y-b.y);for(let t of candidates){addTree(t.x,t.y,t.s);drawTree(t.x,t.y,t.s)}
 for(let i=0;i<35;i++){let x=40+rng()*(W-80),y=40+rng()*(H-80);if(Math.abs(x-W*.76)<280&&Math.abs(y-H*.69)<170)continue;if(dist({x,y},nest)<75)continue;let s=.6+rng()*.8;addRock(x,y,s);drawRock(x,y,s)}
 // A few clusters of collectible food along the trails.
 const specs=[['berry',W*.31,H*.34],['berry',W*.23,H*.29],['seed',W*.62,H*.4],['berry',W*.68,H*.46],['seed',W*.52,H*.65],['berry',W*.41,H*.7],['seed',W*.29,H*.58],['berry',W*.82,H*.35],['seed',W*.16,H*.52],['berry',W*.58,H*.23],['seed',W*.37,H*.23],['berry',W*.18,H*.77],['seed',W*.86,H*.58],['berry',W*.63,H*.82],['seed',W*.45,H*.35],['berry',W*.34,H*.83]];
 for(let [type,x,y] of specs){let px=x+(rng()-.5)*95,py=y+(rng()-.5)*70;resources.push({x:px,y:py,type,available:true,respawn:0});drawPlant(px,py,type,.9+rng()*.3)}
 drawNest();g.strokeStyle='#e4d59c';g.lineWidth=2;g.setLineDash([6,8]);g.beginPath();g.arc(nest.x,nest.y,73,0,Math.PI*2);g.stroke();g.setLineDash([]);
}
function drawAnt(c,x,y,angle,scale=1){c.save();c.translate(x,y);c.rotate(angle);c.scale(scale,scale);c.fillStyle='#18221a65';c.beginPath();c.ellipse(1,6,14,7,0,0,Math.PI*2);c.fill();c.strokeStyle='#35251d';c.lineWidth=2;c.lineCap='round';for(let side of [-1,1])for(let i=0;i<3;i++){let bx=-3+i*5,sy=side*3;c.beginPath();c.moveTo(bx,sy);c.lineTo(bx-3,side*9);c.lineTo(bx-7+(i-1)*2,side*12);c.stroke()}c.fillStyle='#492d24';c.beginPath();c.ellipse(-8,0,6,5.6,0,0,Math.PI*2);c.fill();c.fillStyle='#713b2b';c.beginPath();c.ellipse(1,0,4.2,4,0,0,Math.PI*2);c.fill();c.fillStyle='#925039';c.beginPath();c.arc(10,0,5.2,0,Math.PI*2);c.fill();c.fillStyle='#f3d9a1';c.beginPath();c.arc(12,-2,1.1,0,Math.PI*2);c.fill();c.strokeStyle='#583529';c.lineWidth=1.3;c.beginPath();c.moveTo(12,-4);c.quadraticCurveTo(16,-9,18,-7);c.moveTo(12,4);c.quadraticCurveTo(16,9,18,7);c.stroke();if(ant.carry){c.fillStyle='#d77b6c';c.beginPath();c.arc(-12,-7,4.2,0,Math.PI*2);c.fill();c.fillStyle='#f5c2a0';c.beginPath();c.arc(-13,-8,1.2,0,Math.PI*2);c.fill()}c.restore()}
function drawResources(time){for(const r of resources){if(!r.available)continue;const pulse=1+Math.sin(time*3+r.x)*.08;ctx.save();ctx.translate(r.x,r.y);ctx.fillStyle=r.type==='berry'?'#d97571':'#d6bd73';ctx.globalAlpha=.22+.12*Math.sin(time*3+r.y);ctx.beginPath();ctx.arc(0,-17,13*pulse,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;drawPlant(ctx,0,0,r.type,1);ctx.restore()}}
function resize(){const dpr=Math.min(window.devicePixelRatio||1,2),w=innerWidth,h=innerHeight;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}

