function resize(){const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(innerWidth*dpr);canvas.height=Math.round(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function hud(){document.getElementById('foodCount').textContent=food;const count=food;document.getElementById('objectiveTitle').textContent=count>=5?'¡El nido está bien provisto!':count===0?'Una pequeña misión':`¡Van ${count} de 5!`;document.getElementById('objectiveText').textContent=count>=5?'La colonia celebra tu gran trabajo. Seguí explorando.':count===0?'Explorá el claro y llevá comida al nido.':'Reuní cinco provisiones para la colonia.';const px=(ant.x/W)*100,py=(ant.y/H)*100;miniAnt.style.left=px+'%';miniAnt.style.top=py+'%';document.getElementById('gatherBtn').innerHTML=mode==='gather'||mode==='return'?'<span class="action-icon">↻</span><span>CANCELAR</span>':'<span class="action-icon">🌱</span><span>RECOLECTAR</span>'}
function onNest(){if(dist(ant,nest)<48){if(ant.carry){food+=ant.carry;ant.carry=0;mode='idle';target=null;hud();showToast(food>=5?'¡Provisiones entregadas al nido!':'¡Una provisión más para la colonia!')}else if(mode==='return'){mode='idle';target=null}}}
function collect(){if(!target||!target.available){mode='idle';target=null;return}target.available=false;target.respawn=75;ant.carry=1;mode='return';target=nest;harvestTimer=0;showToast('¡Encontraste una provisión! Volvamos al nido.');hud()}
function isBlocked(x,y){if(x<30||x>W-30||y<30||y>H-30)return true;for(const o of obstacles)if(Math.hypot(x-o.x,y-o.y)<o.r+12)return true;let dx=(x-W*.76)/275,dy=(y-H*.69)/157;if(dx*dx+dy*dy<1)return true;return false}
function steering(goal,dt){let dx=goal.x-ant.x,dy=goal.y-ant.y,d=Math.hypot(dx,dy);if(d<1)return {x:0,y:0};let ux=dx/d,uy=dy/d;const angles=[0,.48,-.48,.9,-.9,1.35,-1.35,1.9,-1.9,2.6,-2.6,Math.PI];let best=null,bestScore=Infinity;for(let a of angles){let ca=Math.cos(a)*ux-Math.sin(a)*uy,sa=Math.sin(a)*ux+Math.cos(a)*uy;let nx=ant.x+ca*ant.speed*dt,ny=ant.y+sa*ant.speed*dt;if(isBlocked(nx,ny))continue;let score=Math.hypot(goal.x-nx,goal.y-ny);for(const o of obstacles){let od=Math.hypot(nx-o.x,ny-o.y)-o.r-12;if(od<25)score+=(25-od)*1.3}if(score<bestScore){bestScore=score;best={x:ca,y:sa}}}return best||{x:0,y:0}}
function move(dir,dt){if(!dir||Math.hypot(dir.x,dir.y)<.04)return;let mag=Math.hypot(dir.x,dir.y);let vx=dir.x/mag,vy=dir.y/mag;ant.angle=Math.atan2(vy,vx);const step=ant.speed*dt;let nx=ant.x+vx*step,ny=ant.y+vy*step;if(!isBlocked(nx,ny)){ant.x=nx;ant.y=ny;return}if(!isBlocked(ant.x+vx*step,ant.y))ant.x+=vx*step;else if(!isBlocked(ant.x,ant.y+vy*step))ant.y+=vy*step}
const keys={};window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key==='Escape')togglePause()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
let stickPointer=null,stickVector={x:0,y:0};const stickShell=document.getElementById('stickShell'),stick=document.getElementById('stick');function stickUpdate(e){const r=stickShell.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.34,d=Math.hypot(dx,dy),ratio=d>max?max/d:1;stickVector={x:dx*ratio/max,y:dy*ratio/max};stick.style.left=`calc(50% + ${stickVector.x*max}px)`;stick.style.top=`calc(50% + ${stickVector.y*max}px)`}
stickShell.addEventListener('pointerdown',e=>{e.preventDefault();stickPointer=e.pointerId;stickShell.setPointerCapture(stickPointer);stickUpdate(e);if(mode!=='idle'){mode='idle';target=null;hud()}});stickShell.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)stickUpdate(e)});function releaseStick(e){if(e.pointerId!==stickPointer)return;stickPointer=null;stickVector={x:0,y:0};stick.style.left='50%';stick.style.top='50%'}stickShell.addEventListener('pointerup',releaseStick);stickShell.addEventListener('pointercancel',releaseStick);
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&stickPointer!==null)return;const rect=canvas.getBoundingClientRect(),scale=renderScale(),cx=innerWidth/2,cy=innerHeight/2,camX=clamp(ant.x-cx/scale,0,W-innerWidth/scale),camY=clamp(ant.y-cy/scale,0,H-innerHeight/scale),wx=camX+(e.clientX-rect.left)/scale,wy=camY+(e.clientY-rect.top)/scale;let res=resources.find(r=>r.available&&Math.hypot(r.x-wx,r.y-wy)<35);if(res){target=res;mode='gather';showToast('Vamos por esa provisión.');hud()}else{target={x:wx,y:wy};mode='move';hud()}});
function renderScale(){return clamp(innerWidth/1050,.68,1)}
function requestGather(){if(mode==='gather'||mode==='return'){mode='idle';target=null;showToast('Exploración libre.');hud();return}let best=resources.filter(r=>r.available).sort((a,b)=>dist(ant,a)-dist(ant,b))[0];if(!best){showToast('Por ahora no quedan provisiones a la vista.');return}target=best;mode='gather';showToast('Buscando la provisión más cercana.');hud()}
function goNest(){mode='move';target=nest;showToast(ant.carry?'¡De vuelta al nido!':'Tu nido está marcado en el mapa.');hud()}
function togglePause(){paused=!paused;document.getElementById('pauseShade').classList.toggle('open',paused);document.getElementById('pauseBtn').textContent=paused?'▶':'Ⅱ'}
document.getElementById('gatherBtn').addEventListener('click',requestGather);document.getElementById('nestBtn').addEventListener('click',goNest);document.getElementById('pauseBtn').addEventListener('click',togglePause);document.getElementById('resumeBtn').addEventListener('click',togglePause);document.getElementById('soundBtn').addEventListener('click',e=>{muted=!muted;e.currentTarget.textContent=muted?'♫':'♪';showToast(muted?'Sonido desactivado':'Sonido activado')});

